  -- Imhûlar / Discovering Imhûlar
  [1879491625] = {
      [1] = {
      ["NAME"] = "Kûr Anzar"; 
      ["PROGRESS"] = "Find Kûr Anzar"; 
      ["LORE"] = "Kûr Anzar is a fortified town built among the ruins of a Númenórean citadel that was itself constructed on the bones of an ancient Khandari stronghold. This was originally the ruling seat of the Shâr of Hamât, but centuries of civil warfare and invasion from Gondor have laid waste to it. Now Kûr Anzar is mainly held by the Ordâkhai remnant and cultists who serve the Church of the All-seeing."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.78S"; 
          ["LONG"] = "61.55W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Vartúlin"; 
      ["PROGRESS"] = "Find Vartúlin"; 
      ["LORE"] = "Vartúlin is the last surviving Kinta grove in the dying woods of Imhûlar, a resting-place for many honoured elders among the Kintai. Even this refuge has begun to suffer as the despoiling contagion finally overcomes the Elf-magic that protected it for so long."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.84S"; 
          ["LONG"] = "64.43W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Urmâkh"; 
      ["PROGRESS"] = "Find Urmâkh"; 
      ["LORE"] = "The town of Urmâkh in western Imhûlar has become home to many of the Shagâni residents displaced from Kûr Anzar. Their anger at the soldiers of Ordâkh is matched, if not exceeded, by their hatred for the despots of Gondor who feature prominently in the tales and legends of their land."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.61S"; 
          ["LONG"] = "66.90W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Tûl Zakana"; 
      ["PROGRESS"] = "Find Tûl Zakana, the Well of Forgetting"; 
      ["LORE"] = "Hidden deep within war-torn Imhûlar, an Ordâkh-controlled trading post traffics in phials of liquid with a dangerous reputation: water from Tûl Zakana, the Well of Forgetting. Locals advise you steer clear of Tûl Zakana, for many have vanished in its vicinity. Did they run afoul of the Ordâkhai, or did they imbibe too greedily of the waters and lose all sense of themselves?"; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.84S"; 
          ["LONG"] = "56.14W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Tombs of Esh-kimâkhi"; 
      ["PROGRESS"] = "Find the Tombs of Esh-kimâkhi"; 
      ["LORE"] = "The Tombs of Esh-kimâkhi, the 'hallows of the three,' were constructed by Aragín the Queller, first King of Hamât. The triple crypt was built in memory of the three great enemies he slew before sundering his sword and devoting the rest of his life to peace."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.53S"; 
          ["LONG"] = "61.76W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Watcher of Urmâkh"; 
      ["PROGRESS"] = "Find the Watcher of Urmâkh"; 
      ["LORE"] = "This hilltop prominence was carved by the peoples of old Hamât to resemble a lion's head overlooking the dying forests and the lands downstream."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.91S"; 
          ["LONG"] = "72.70W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Dag Usakâra"; 
      ["PROGRESS"] = "Find Dag Usakâra"; 
      ["LORE"] = "This is the home of Usakâr, an aged hermit who lives in the forest and keeps to the old ways of venerating the guardians of the wood. The extent of his secret knowledge is unknown even to the Kintai, who count themselves among his friends. He despairs over the death of the trees, and hopes there may be some means of reversing the pestilence that consumes them."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "43.03S"; 
          ["LONG"] = "62.77W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Kûgrun"; 
      ["PROGRESS"] = "Find Kûgrun"; 
      ["LORE"] = "Some among the Kintai whisper of Kûgrun, the Golden Sanctuary, a place of peace located somewhere in the dying forest. When pressed, they will hesitate to speak of its true location for reasons of their own."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "43.87S"; 
          ["LONG"] = "65.73W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Span of Nâmbadir"; 
      ["PROGRESS"] = "Find Nâmbadir, the Span of Princes"; 
      ["LORE"] = "This tall and timeworn stone bridge crossing the Ikorbân was originally constructed by the Númenóreans as part of their project to channel the river. The name 'Span of Princes' was given to the bridge in honour of two princes of Gondor who fell in battle near this location."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "32.89S"; 
          ["LONG"] = "59.87W"; 
        }; 
      }; 
      };
  };
