  -- Imhûlar / Dangers of Imhûlar
  [1879491627] = {
      [1] = {
      ["NAME"] = "Dûlagig"; 
      ["PROGRESS"] = "Find Dûlagig"; 
      ["LORE"] = "The scorpions of Dûlagig dwell too near to the village of Urmâkh for the residents to feel completely comfortable, but some have devised healing remedies that make use of scorpion parts. These useful purposes help to keep the creatures from becoming too numerous."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.07S"; 
          ["LONG"] = "66.77W"; 
        }; 
      }; 
      };
      [2] = {
      ["NAME"] = "Mûr Igam"; 
      ["PROGRESS"] = "Find Mûr Igam"; 
      ["LORE"] = "The scorpions at Mûr Igam dwell in the shadow of Kûr Anzar, and it appears they have not troubled the soldiers and cultists who now occupy the city. Should that change, each side may find itself unprepared to overcome the challenge posed by the other."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.09S"; 
          ["LONG"] = "62.19W"; 
        }; 
      }; 
      };
      [3] = {
      ["NAME"] = "Shakhdag"; 
      ["PROGRESS"] = "Find Shakhdag"; 
      ["LORE"] = "The boars of Shakhdag have not escaped the pestilence that holds Imhûlar in its grip."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.03S"; 
          ["LONG"] = "69.10W"; 
        }; 
      }; 
      };
      [4] = {
      ["NAME"] = "Róthirin"; 
      ["PROGRESS"] = "Find Róthirin"; 
      ["LORE"] = "The Curthádi spirits that haunt Róthirin were born from the sickness and death that claimed the woods where a living Kinta faded into one of the Vairi. Now these spirits serve the Dark Lord Sauron, despite his recent defeat."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "42.63S"; 
          ["LONG"] = "60.80W"; 
        }; 
      }; 
      };
      [5] = {
      ["NAME"] = "Adakûr"; 
      ["PROGRESS"] = "Find Adakûr"; 
      ["LORE"] = "Wights stalk the crypts of Adakûr, the outermost reaches of the graveyard that also contains the triple tomb built by Aragín the Queller before he walked the path of peace. The names of the ancient ones buried in Adakûr are not as well-known as the three great enemies for whom Aragín constructed Esh-kimâkhi."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.00S"; 
          ["LONG"] = "63.20W"; 
        }; 
      }; 
      };
      [6] = {
      ["NAME"] = "Zahûmakh"; 
      ["PROGRESS"] = "Find Zahûmakh"; 
      ["LORE"] = "Some creatures, like the bog-lurkers of Zahûmakh, remain hardy enough to survive among the pools in south-east Imhûlar, despite the pestilence that endangers the woods."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "43.61S"; 
          ["LONG"] = "57.62W"; 
        }; 
      }; 
      };
      [7] = {
      ["NAME"] = "Ghât Lor"; 
      ["PROGRESS"] = "Find Ghât Lor"; 
      ["LORE"] = "The Ordâkhai threaten the woods nearby from their hidden encampment of Ghât Lor, among the rocks in south-eastern Imhûlar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "40.54S"; 
          ["LONG"] = "57.86W"; 
        }; 
      }; 
      };
      [8] = {
      ["NAME"] = "Ghât Okho"; 
      ["PROGRESS"] = "Find Ghât Okho"; 
      ["LORE"] = "Crebain flit over the pools of Ghât Okho in eastern Imhûlar, but the fish they seek to claim have succumbed to disease and pestilence."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "38.21S"; 
          ["LONG"] = "55.76W"; 
        }; 
      }; 
      };
      [9] = {
      ["NAME"] = "Tir Katar"; 
      ["PROGRESS"] = "Find Tir Katar"; 
      ["LORE"] = "Servals stalk among the rubble that might once have housed residents of Urmâkh, but the people have long since fled and their home is now a ruin."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "36.72S"; 
          ["LONG"] = "65.66W"; 
        }; 
      }; 
      };
      [10] = {
      ["NAME"] = "Tharháth"; 
      ["PROGRESS"] = "Find Tharháth"; 
      ["LORE"] = "A band of Orcs has set up camp at Tharháth to watch the road leading north out of Imhûlar by way of the Bridge of Princes."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "33.23S"; 
          ["LONG"] = "60.67W"; 
        }; 
      }; 
      };
      [11] = {
      ["NAME"] = "Fotak-dâr"; 
      ["PROGRESS"] = "Find Fotak-dâr"; 
      ["LORE"] = "Orcs have claimed this street in Kûr Anzar for their own. Despite the fall of Sauron, they still maintain their allegiance to the Church of the All-seeing and provide what aid they can to the cultists of Barkhûsh."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "37.93S"; 
          ["LONG"] = "61.05W"; 
        }; 
      }; 
      };
      [12] = {
      ["NAME"] = "Dûl Zidur"; 
      ["PROGRESS"] = "Find Dûl Zidur"; 
      ["LORE"] = "Cultists of Barkhûsh serve the Church of the All-seeing from Dûl Zidur, north-east of Kûr Anzar, with instructions to meet here in the event anything harms their hold upon the central city of Imhûlar."; 
      ["POINTS"] = {
        [1] = {
          ["LAT"] = "35.80S"; 
          ["LONG"] = "57.44W"; 
        }; 
